\label{thm_main}  
  Let  $\alpha\in (0,1]$ and $\gamma\in \mathbb R_{>0} \setminus \{1\}$, and  $2\le q,r \leq \infty$ with $(d/\alpha, q,r)\neq (2 ,2,\infty)$.  Suppose that $E$ is a bounded set with bounded $\alpha$-Assouad characteristic. 
 Then,  the estimate 
\begin{equation} \label{f-stri}    \sup_{j\ge 1}   \big\| U^\gamma_t P_j f\big\|_{L_t^q( E(2^{-\gamma j}); L_x^r)} + \big\| U^\gamma_t P_{\le 0} f\big\|_{L_t^q( E(1); L_x^r)}   \le C [E]_\alpha^\frac1q \|f\|_{H^s} \end{equation}
 holds   provided that $(q,r)$ satisfies 
 \begin{equation} 
 \label{con-ad} 
\frac d2 \Big(\frac 12 - \frac1r\Big) \ge  \frac \alpha q
 \end{equation} 
 and 
  \begin{equation} 
 \label{con-reg} 
 s\ge    s_\gamma (q,r):= \frac d2-\frac d r  - \frac {\gamma} q . 
 \end{equation}

\label{homo-homo}   Let  $\alpha\in (0,1]$, $\gamma\in \mathbb R_{>0} \setminus \{1\}$, and  $2\le q,r \leq \infty$ with $(d/\alpha, q,r)\neq (2 ,2,\infty)$ and $\frac d r  + \frac {\gamma} q < d$.  Suppose that $E$ has bounded $\alpha$-Assouad characteristic.  Then,  the estimate 
\begin{equation} 
\label{f-stri-hs}   \sup_{-\infty< j <\infty}  \big\| U^\gamma_t P_j f\big\|_{L_t^q( E(2^{-\gamma j}); L_x^r)} \le C [E]_\alpha^\frac1q \|f\|_{\dot H^{s}}
\end{equation}
 holds   if $(q,r)$ satisfies \eqref{con-ad}  and $s=s_\gamma(q,r)$.

\label{cor_main} 
 Let  $\alpha\in (0,1]$, $\gamma\in \mathbb R_{>0} \setminus \{1\}$, and  $2\le q,r \leq \infty$ with $(d/\alpha, q,r)\neq (2 ,2,\infty)$.
  Suppose that   $\mu$ has  bounded support and satisfies  \eqref{alpha-dim}. Then, we have 
 \begin{equation} \label{f-stri10}   \| U^\gamma_t f\|_{L_t^q( \mathrm{d}\mu ; L_x^r)} \le C\langle \mu\rangle_\alpha^\frac1q\|f\|_{H^s}\end{equation}
  provided that \eqref{con-ad} holds and 
  \begin{align}\label{con-reg2}
  	s\ge s_{\gamma\alpha}(q,r).
\end{align}

\label{cor_m} 
 Let  $\alpha\in (0,1]$, $\gamma\in \mathbb R_{>0} \setminus \{1\}$, and  $2\le q,r \leq \infty$ with $(d/\alpha, q,r)\neq (2 ,2,\infty)$ and $\frac d r  + \frac {\gamma} q < d$. 
  Suppose that   $\mu$  satisfies  \eqref{alpha-dim}. Then, we have 
 \begin{equation} \label{f-stri1}   \| U^\gamma_t f\|_{L_t^q( \mathrm{d}\mu ; L_x^r)} \le C\langle \mu\rangle_\alpha^\frac1q\|f\|_{\dot H^s}\end{equation}
  provided that \eqref{con-ad} holds and $s=s_{\gamma\alpha}(q,r)$.

\label{thm_inhom1}  
Let $\gamma\ge 2$, $\alpha\in (0, d/\gamma)\cap(0,1]$,  and $2 \le \tilde r, r<\infty$.  
	Suppose that    
	\[
	(1/\tilde r, 1/ r)\in \mathcal H \setminus\{C, C'\}
	\] and  the exponents $q, \tilde q\in [2, \infty]$ satisfy 
		\begin{align}
		0&\le \frac 1q \le \frac 1 {\tilde q\,'} \le  1 - \frac{d}{2\alpha} \Big( \frac1r  - \frac1{\tilde r}\Big),  \hspace{-2.5cm} &&  \text{ if } \  \frac1r \ge \frac 1{\tilde r}, \label{ran_q_up}\\
		&\,\, \frac{d}{2\alpha} \Big(\frac1{\tilde r}- \frac1r \Big) \le \frac 1q \le \frac 1 {\tilde q\,'} \le 1,   \hspace{-2.5cm}  && \text{ if } \  \frac1r \le \frac 1{\tilde r}.\label{ran_q_low}
	\end{align}
 Then, 
	we have the estimate \eqref{f-inhom} and 
	\begin{align}
	\label{inho-est}
		\Big\| \int_{[0,t]} \mathrm{e}^{-i(t - s)(-\Delta)^{\gamma/2}} F(s)\,\mathrm{d}\mu (s) \Big\|_{L_t^q\left( \mathrm{d}\mu; L_x^{r} \right)} 
		\le C  \| F\|_{L_s^{\tilde{q}'}(\mathrm{d}\mu ; L_x^{\tilde{r}' })}.
	\end{align}

\label{thm_LS}
Let $\gamma >1$.  

Suppose that   $\mu$ is a measure  $\mu$ with $\operatorname{supp} \mu\subset [0,1]$ satisfying  \eqref{alpha-dim}.
Then, for any $s \geq  \alpha 
(1-\gamma)/2$, there exists $C$ such that
\begin{equation} 
\label{ls-s}
	\left\| U_t^\gamma f \right\|_{L_{t}^2 (\mathrm d\mu; L^2_x(\mathbb{B}^d))} \leq C \|f\|_{H^s}.
\end{equation}

\label{thm_LS-homo}
Let $\gamma >1$, and $E\subset [0,1]$.  

Suppose that $E$ has bounded $(\alpha, (\gamma-1)/\gamma)$-Assouad characteristic.
Then, for any $s \geq  
(\alpha-\gamma)/2$, there exists $C$ such that
\begin{equation} 
\label{ls-s-homo}
	\sup_{j\ge 1} \left\| U_t^\gamma P_j f \right\|_{L_{t}^2 ((E(2^{-\gamma j}); L^2_x(\mathbb{B}^d))}  +  \big\| U^\gamma_t P_{\le 0} f\big\|_{L_t^2( E(1); L_x^2(\mathbb{B}^d))} \leq C \|f\|_{H^s}.
\end{equation}

\label{lem_Str} Let  $\alpha\in (0,1]$ and $\gamma\in \mathbb R_{>0} \setminus \{1\}$, and  $2\le q,r \leq \infty$ with $(d/\alpha, q,r)\neq (2 ,2,\infty)$.  Suppose that $E$ has bounded $\alpha$-Assouad characteristic. Then, for $j\in \mathbb Z$,  we have
	\begin{equation}
	\label{250309_0149c} 
		 \| U_{t}^\gamma P_j f\|_{L_{t}^q(E(2^{-\gamma j})  ;L^r_x)} \leq C 2^{(\frac d2 - \frac dr-\frac \gamma q)j}  [E]_\alpha^\frac1q \|f\|_{2}  
	\end{equation}
	whenever \eqref{con-ad}  holds.

\label{lem_250901}  Let $1\le q,r\le \infty$, and $\tau\in \mathbb R$.  Then,  for  $j\in \mathbb Z$, we have
 \begin{equation} 
 \label{equiv}
 \| U_t^\gamma P_j f\|_{L_t^q(I_{\tau}; L_x^r)}\sim 2^{-j \frac \gamma q} \|U_{\tau}^\gamma P_j f\|_{L_x^r},
 \end{equation}
 with the implicit constants independent of $j$.

\label{lem_discrete_Str}   Let $\gamma\in \mathbb R_{>0} \setminus \{1\}$. Let  $\alpha\in (0,1]$ and  $2\le q,r \leq \infty$ with $(d/\alpha, q,r)\neq (2 ,2,\infty)$. Suppose that $E$ has bounded $\alpha$-Assouad characteristic and $\mathcal E_j$  is  a $2^{-\gamma j }$-separated subset of   $E$. Then we have
	\begin{equation}
	\label{250309_0149} 
		 \| U_{\tau}^\gamma P_j f\|_{\ell_{\tau}^q( \mathcal E_j  ;L^r_x)} \leq C 2^{jd(\frac 12 - \frac 1r)} [E]_\alpha^\frac1q \|f\|_{2}
	\end{equation}
	with $C$ independent of  the choice of  $\mathcal E_j$ whenever \eqref{con-ad}  holds.

\label{rr'} For $t,s\in \mathbb R$, let 
\begin{equation} 
\label{gr}
 \mathcal K_r(t, s) =(1+ 2^{\gamma j }|t-s|)^{-d(\frac1 2 - \frac1 r)} .
 \end{equation}
Then, for $2\le r\le \infty$ and $t,s\in \mathbb R$, we have 
\begin{equation}\label{250309_1101}
	\| T_{t, s} g\|_{L_x^r} \le C 2^{2jd(\frac1 2 - \frac1 r)} \mathcal K_r(t, s)\| g\|_{L_x^{r'}}. 
\end{equation}

The Plancherel theorem gives
\begin{equation}\label{250309_1459}
	\| T_{t, s}  g \|_{L_x^2} \leq \| g\|_{L^2_x}
\end{equation}
for $t,s\in \mathbb R$. Note that the kernel $K_{t, s}$ of  the operator $T_{t, s}$ is given by 
\[  K_{t, s}(x, y)=  (2\pi)^{-d} \int_{\mathbb{R}^d} \mathrm{e}^{i ( (t-s)|\xi|^\gamma + \langle x-y, \xi \rangle)}\psi^2(|\xi|/2^j)\,\mathrm{d}\xi.\]
Since the Hessian matrix of $|\xi|^\gamma$, $\gamma\neq 1$ has non-vanishing determinant when $|\xi|\sim 1$, 
after scaling $\xi\to 2^j\xi$, using  the stationary phase estimate, we have 
\begin{align*}
	\big|  K_{t, s}(x, y)\big| \le C 2^{dj} \min\{ ( 2^{\gamma j }|t - s|)^{-\frac d2}, 1\}, 
\end{align*}
which gives 
\begin{equation}\label{250309_1100}
	\| T_{t, s} g \|_{L_x^\infty} \le C 2^{dj}  (1+ 2^{\gamma j }|t - s|)^{-\frac d2} \|g\|_{L_x^1}.
\end{equation}
Interpolating \eqref{250309_1459} and \eqref{250309_1100} yields  \eqref{250309_1101} for $2\le r\le \infty$ and $t,s\in \mathbb R$.

\label{young}  Let $\mathcal E$ be a discrete subset of $\mathbb R$. 
\begin{itemize}
\item[{\bf (A)}] Suppose  that 
\[  
\sup_{\tau'\in \mathcal E} \|\mathcal K(\cdot, \tau')\|_{\ell^{s}_\tau (\mathcal E)}, \quad  \sup_{\tau \in \mathcal E}    \|\mathcal K(\tau,\cdot)\|_{\ell^{s}_{\tau'} (\mathcal E)} \le B\]  for some $1\le s\le \infty$. Then, we have 
\begin{equation}
\label{seq}
\Big\|  \sum_{\tau' \in  \mathcal E }  \mathcal K(\tau, \tau')\, a_{\tau'}  \Big\|_{\ell_\tau^{q}(\mathcal E)} \le C B \| a_\tau \|_{\ell_\tau^{p}(\mathcal E)} 
\end{equation}
if $1/p-1/q=1-1/s$ and $1\le p, q\le \infty$.  

\item[{\bf (B)}]  Suppose  that 
\[ \sup_{\tau'\in \mathcal E} \|\mathcal K(\cdot, \tau')\|_{\ell^{s,\infty}_\tau (\mathcal E)},\quad \sup_{\tau \in \mathcal E}    \|\mathcal K(\tau,\cdot)\|_{\ell^{s,\infty}_{\tau'} (\mathcal E)}\le B\] 
 for some $1< s< \infty$.  
Then,  we have the estimate  \eqref{seq} 
provided that $1/p-1/q=1-1/s$ and $1< p, q< \infty$.
\end{itemize}

\label{kernel} Let $r>2$, and let  $\mathcal K_r$  be given by \eqref{gr}. If  $d(\frac1 2 - \frac1 r)> \frac \alpha s $, then we have
\begin{equation} 
\label{strong}
\sup_{\tau'\in \mathcal E_j}  \|\mathcal K_r(\cdot, \tau')\|_{\ell^{s}_\tau (\mathcal E_j)}, \quad  \sup_{\tau \in \mathcal E_j}    \|\mathcal K_r(\tau,\cdot)\|_{\ell^{s}_{\tau'} (\mathcal E_j)} \le C[E]_\alpha^\frac1s
\end{equation}
for a constant $C$, independent of $j$.   Moreover,  if $d(\frac1 2 - \frac1 r)= \frac \alpha s $, then 
\begin{equation} \label{weak}
\sup_{\tau'\in \mathcal E_j}  \|\mathcal K_r(\cdot, \tau')\|_{\ell^{s,\infty}_\tau (\mathcal E_j)}, \quad  \sup_{\tau \in \mathcal E_j}    \|\mathcal K_r(\tau,\cdot)\|_{\ell^{s,\infty}_{\tau'} (\mathcal E_j)} \le C[E]_\alpha^\frac1s
\end{equation} for a constant $C$, independent of $j$.

\label{lem_interpol1}
For $1\le a, b\le \infty$, let 
 \[ \lambda(a, b) = \frac d2 \Big(1 - \frac1a - \frac1b\Big).\] 
If  $(1/{a}, 1/{b})$ are contained in the interior of the quadrangle $\mathcal Q$ $($with vertices $(0,0)$,  $A=(1/2, 1/r_\ast)$,   $(1/2, 1/2)$, and  $A'=(1/r_\ast, 1/2),$ see \eqref{r*}$)$, 

  we have
	\begin{equation}
	\label{k-loc}		|\mathcal{B}_k (F, G)| \lesssim 2^{2\lambda(a,b)j } 2^{(\alpha-\lambda(a, b))k}  [E]_\alpha \|F \|_{\ell_\tau^2(\mathcal E_j; L_x^{a'})}\|G \|_{\ell_\tau^2(\mathcal E_j; L_x^{b'})}.
\end{equation}

The estimate \eqref{k-loc} for $(a,b)=(2,2)$ and $(a,b)=(\infty, \infty)$  is easy to show. Indeed, from \eqref{sumk}  and \eqref{250309_1101}, we have
\[ |\mathcal{B}_k (F, G)|  \le C  2^{2j\lambda(r,r)}  \sum_{\tau, \tau'} \mathcal K_{r,k}(\tau, \tau')  \| F(\tau)\|_{L_x^{r'}}\| G(\tau')\|_{L_x^{r'}}\]
for $2\le r\le \infty$, where    $\mathcal K_{r,k}$ is given by  \eqref{K-chi}.

Therefore,  the Cauchy--Schwarz inequality gives
\begin{equation} 
\label{00-22}
 |\mathcal{B}_k (F, G)|  \le 2^{2j\lambda(r,r)}  \Big\|  \sum_{\tau} \mathcal K_{r,k}(\tau, \tau')\| F(\tau)\|_{L_x^{r'}}\Big\|_{\ell^2(\mathcal E_j)}  \|G(\tau')\|_{\ell^2(\mathcal E_j; L_x^{r'})}.
 \end{equation}
From \eqref{gr}, it follows that $\mathcal K_{r,k} \le  2^{-\lambda(r, r) k}\chi_{k}$.   Since $\| \chi_{k}(\cdot - \tau')\|_{\ell^1(\mathcal E_j)}= \# A_k (\tau')$,  recalling \eqref{ak},  we see that 
\begin{equation} \label{kr-norm} \sup_{\tau'\in \mathcal E_j}  \|\mathcal K_{r,k}(\cdot, \tau')\|_{\ell^{1}_\tau (\mathcal E_j)},  \,\,  \sup_{\tau \in \mathcal E_j}    \|\mathcal K_{r,k}(\tau,\cdot)\|_{\ell^{1}_{\tau'} (\mathcal E_j)}   \le  C  2^{(\alpha-\lambda(r, r))k} [E]_\alpha.\end{equation}
Therefore, applying  {\bf (A)} in  Lemma \ref{young} with $p=q=2$,  we have \eqref{k-loc}, in particular,  for  $(a,b)=(2,2)$ and $(a,b)=(\infty, \infty)$. 


Therefore, in perspective  of interpolation, it suffices to show
	\begin{align}
	\label{1st}
		|\mathcal{B}_k (F, G)| 
	&\lesssim 2^{d(\frac12 - \frac1r)j } 2^{( \alpha-\frac d2 (\frac12 - \frac1r) )k} [E]_\alpha \|F\|_{\ell_\tau^2(\mathcal E_j; L_x^2)} \| G\|_{\ell_\tau^2(\mathcal E_j; L_x^{r'})},
	\\[4pt]
	\label{2nd}
	|\mathcal{B}_k (F, G)| 
	&\lesssim 2^{d(\frac12 - \frac1r)j } 2^{( \alpha-\frac d2 (\frac12 - \frac1r) )k}  [E]_\alpha \|F\|_{\ell_\tau^2(\mathcal E_j; L_x^{r'})} \| G\|_{\ell_\tau^2(\mathcal E_j; L_x^2)}
	\end{align}
	for $2\leq r < r_\ast$.  By symmetry, we only have to show \eqref{1st}. Indeed, observe that 
	\[ \mathcal{B}_k (F, G)= \overline{\mathcal{B}_k (G, F)} .\] 
	Thus, \eqref{2nd} follows from \eqref{1st}. 


Thanks to the cutoff function $\chi_{k}(\tau - \tau')$, using a standard argument, we may assume that $\operatorname{supp} F(x,\cdot)$ and $\operatorname{supp} G(x,\cdot)$ are contained  in an interval of length $2^k2^{-\gamma j }$ for all $x$ (see Remark \ref{interval} below). 


We now claim that
\begin{equation}\label{claim_endpoint}
	\Big\| \sum_{\tau'} \chi_{k}(\tau -  \tau') (U_{\tau'}^\gamma P_j)^* G(\tau') \Big\|_{L_x^2} \!
	\lesssim  2^{d(\frac12 - \frac1r)j} 2^{( \frac \alpha 2-\frac d2(\frac12 - \frac1r))k} [E]_\alpha^\frac12 \| G\|_{\ell_{\tau'}^{2}(\mathcal E_j; L_x^{r'})}
\end{equation}
holds for $2\leq r < r_\ast$ and uniformly in $\tau$.  Assuming this for the moment, we prove \eqref{1st}. 
Observe that
\begin{align*}
	|\mathcal{B}_k (F, G)| & \le \sum_{\tau}\Big| \Big\langle (U_\tau^\gamma P_j)^* F(\tau), \sum_{\tau'} \chi_{k}(\tau -\tau')(U_{\tau'}^\gamma P_j)^* G(\tau')\Big\rangle_x\Big|.
	\end{align*}
	Thus, the  Cauchy--Schwarz inequality and \eqref{claim_endpoint}  give
	\begin{align*}
	|\mathcal{B}_k (F, G)|
	&\leq \sum_{\tau} \| F(\tau)\|_{L_x^2} \Big\| \sum_{\tau'}\chi_{k}(\tau - \tau')(U_{\tau'}^\gamma P_j)^* G(\tau') \Big\|_{L_x^2}
	\\
	&\le C  2^{d(\frac12 - \frac1r)j} 2^{( \frac \alpha 2-\frac d2(\frac12 - \frac1r))k} [E]_\alpha^\frac12  \|F\|_{\ell_\tau^{1}(\mathcal E_j; L_x^2)} 
	 \| G\|_{\ell_{\tau'}^{2}(\mathcal E_j; L_x^{r'})}. 
\end{align*}
Note that we are assuming $\operatorname{supp} F(x,\cdot)$ is contained in an interval $J$ of length  $\sim 2^k2^{-\gamma j }$. 
Since  $\mathcal E_j$ is a $2^{-\gamma j}$-separated  subset of $E$ with bounded $\alpha$-Assouad characteristic, as before,  we have $\#\{\tau\in \mathcal E_j:  \tau\in J\}\le C 2^{\alpha k} [E]_\alpha$. Thus,  H\"older's inequality gives
$\|F\|_{\ell_\tau^{1}(\mathcal E_j; L_x^2)} \le C2^{ \frac\alpha 2 k }[E]_\alpha^\frac12 \|F\|_{\ell_\tau^{2}(\mathcal E_j; L_x^2)}$, and hence \eqref{1st} follows. 

It remains to verify the claim \eqref{claim_endpoint}.  Recalling  \eqref{utut} and \eqref{chi-k} and repeating the similar argument as before ({\it cf.}  \eqref{hoho}, 
we note that 
\eqref{claim_endpoint} follows if we show 
\begin{align*}
	\Big|  \sum_{\tilde \tau\in {\mathcal E}_j}  \Big\langle  \sum_{ \tau'\in{\mathcal E}_j }  \tilde \chi_k(\tilde \tau, \tau') T_{\tilde \tau, \tau'} G(\tau'), G(\tilde\tau)\Big\rangle\Big|
	\lesssim  2^{2d(\frac12 - \frac1r)j } 2^{(\alpha- d(\frac12 - \frac1r))k}  [E]_\alpha \| G\|_{\ell_{\tau'}^{2}({\mathcal E}_j; L_x^{r'})}^2.
\end{align*}
for $2\le r\le r_\ast$, where 
\[    \tilde \chi_k(t, s)=  \chi_k (\tau - t) \chi_k (\tau - s).\]  

By applying  H\"older's,  Minkowski's and Cauchy--Schwarz's inequalities successively and following the same argument as in the proof of Proposition~\ref{lem_discrete_Str}, one sees  that  the matter is reduced to showing 
\[  \Big\| \sum_{ \tau' \in  {\mathcal E}_j }   \tilde \chi_k(\tilde \tau, \tau')  \|T_{\tilde\tau, \tau'} G(\tau')\|_{L_x^{r}} \Big\|_{\ell_{\tilde \tau}^{2}({\mathcal E}_j )} \lesssim [E]_\alpha 2^{2d(\frac12 - \frac1r)j } 2^{(\alpha- d(\frac12 - \frac1r))k} \| G\|_{\ell_{\tau'}^{2}({\mathcal E}_j ; L_x^{r'})}. \]
By \eqref{250309_1101}, this in turn follows from 
\begin{equation} 	 
\label{rr-22}
\Big\| \! \sum_{ \tau' \in \mathcal E_j }   \tilde \chi_k(\tilde \tau, \tau') \mathcal K_r(\tilde\tau, \tau') \|G(\tau')\|_{L_x^{r'}} \Big\|_{\ell_{\tilde \tau}^{2}({\mathcal E}_j )}\! \lesssim \![E]_\alpha 2^{(\alpha- d(\frac12 - \frac1r))k} \| G\|_{\ell_{\tau'}^{2}({\mathcal E}_j ; L_x^{r'})}. 
\end{equation}

Note that $ \tilde \chi_k(\tilde \tau, \tau') =0$ if $|\tilde \tau- \tau'|\ge 2^{k-\gamma j+2}$.  Using the same decomposition as before,  by \eqref{gr} and \eqref{ak}, we obtain 
\[ 
 \|  \tilde \chi_k(\tilde \tau, \cdot)  \mathcal K_r(\tilde \tau, \cdot)\|_{\ell^1_{\tau'}(\mathcal E_j)} \le \! \! \sum_{0\le l\le k+2} \! \| \chi_l (\tilde \tau, \cdot)  \mathcal K_r(\tilde \tau, \cdot) \|_{\ell^1_{\tau'}(\mathcal E_j)} \lesssim \!  [E]_\alpha \! \! \sum_{0\le l\le k+2}  \!  2^{(\alpha- d(\frac12 - \frac1r))l }.
 \]
Since $r<r_\ast$,  it follows that 
\[\sup_{\tilde \tau \in  \mathcal E_j } \| \tilde \chi_k(\tilde \tau, \cdot) \mathcal K_r(\tilde \tau, \cdot)   \|_{\ell_{\tau'}^{1}({\mathcal E}_j )} \lesssim [E]_\alpha 2^{(\alpha- d(\frac12 - \frac1r))k}.   \] 
By symmetry the same estimate also holds for  $\sup_{ \tau'\in  \mathcal E_j }   \| \tilde \chi_k(\cdot, \tau') \mathcal K_r(\cdot, \tau')   \|_{\ell_{\tilde \tau}^{1}({\mathcal E}_j )}$.  Therefore, from  {\bf (A)} in  Lemma \ref{young} with $p=q=2$,  we obtain the desired inequality.

\label{interval}  Let $1\le \tilde q'\le q\le \infty$.    Suppose the estimate  
\begin{equation}
\label{Bk}
| \mathcal{B}_k (F,G) |\le B \|F\|_{\ell^{q'}(\mathcal E_j; X)} \|G\|_{\ell^{\tilde q'}(\mathcal E_j; Y)}
\end{equation} 
holds whenever   $\operatorname{supp} F(x, \cdot)$ and $\operatorname{supp}  G(x, \cdot)$  are contained in an interval of length $2^{k-\gamma j +2}$ for all $x$.  
Here $X$ and $Y$ denote appropriate $L_x^p$ spaces.   Then, the same estimate \eqref{Bk} remains valid without the  assumption on the support of $F, G$. 

Indeed, let  $\mathcal{I}=\{I\}$ be a family  of disjoint intervals $I$ with $|I|=2^k 2^{-\gamma j }$ partitioning $\mathbb R$. Set 
\[ F = \sum_{I\in \mathcal I} F_I, \quad G = \sum_{I\in \mathcal I}G_{I},\] where $F_I(x,t)=F(x,t)\chi_I(t)$ and $G_{I}(x,t)= G(x,t)\chi_I(t)$.
Then,  by the assumption  it follows that 
\begin{align*}
	| \mathcal{B}_k (F,G) | &\le \sum_{I, I'\in \mathcal I: \operatorname{dist}(I,I')\le 2^k2^{-\gamma j }}  |\mathcal{B}_k (F_I,G_{I'}) |.
\\ 
 &\le \sum_{I, I'\in \mathcal I: \operatorname{dist}(I,I')\le 2^k2^{-\gamma j }} B \|F_I\|_{\ell^{q'}(\mathcal E_j; X)} \|G_{I'}\|_{\ell^{\tilde q'}(\mathcal E_j; Y)},
\end{align*}
Since $I$ are disjoint intervals of length $2^{k-\gamma j}$,   H\"older's inequality and disjointness of the intervals yield
\begin{align*}
	| \mathcal{B}_k (F,G) | 
	   &\lesssim  B  \Big( \sum_{I \in \mathcal I} \|F_I\|_{\ell^{q'}(\mathcal E_j; X)}^{q'}  \Big)^{1/{q'}}   \Big( \sum_{I \in \mathcal I}  \|G_I\|_{\ell^{\tilde q'}(\mathcal E_j; Y)}^{q}\Big)^{1/q} 
	   \\
	    &\le B   \|F\|_{\ell^{q'}(\mathcal E_j; X)}    \|G\|_{\ell^{\tilde q'}(\mathcal E_j; Y)} .
\end{align*}
For the second inequality we use the fact that $\tilde q'\le q$.

\label{lem_bi_interpol}\cite[Section 3.13.5(b)]{BerLof}
	Let $A_0, A_1, B_0, B_1, C_0, C_1$ be Banach spaces, and the bilinear operator $T$ be such that 
	\begin{align*}
		T : A_{i} \times B_j \to C_{i+j}
	\end{align*}
	is  bounded for $(i,j)=(0,0),$ $(0,1),$ and $(1,0)$. 
	Then, for $0<\alpha_0, \alpha_1, \alpha = \alpha_0+\alpha_1<1$, $1\leq p,q,r\leq\infty$, and $1\leq 1/p+ 1/q$, 
	\[
		T : (A_0, A_1)_{\alpha_0, pr} \times (B_0, B_1)_{\alpha_1, qr} \to (C_0, C_1)_{\alpha, r}
	\]
	is bounded. 
Here, $(A_0, A_1)_{\alpha, p}$	denotes the real interpolation space (in the sense of the $
K$-method) between $A_0$ and  $A_1$.

\label{wave-homo} Let $d\ge 2$. The same argument also works for the wave operator, i.e., $\gamma=1$. 
 When $\gamma=1$, the stationary phase method gives
\begin{equation}
\label{dis-wave}
	\| T_{\tau, \tau'} g \|_{L_x^\infty} \le C 2^{dj}  (1+ 2^{\gamma j }|\tau - \tau'|)^{-\frac {d-1}2} \|g\|_{L_x^1}
	\end{equation}
 instead of \eqref{250309_1100}. Thus, a routine adaptation of the previous argument  proves 
 the estimate  \eqref{f-stri}  for $(q,r)\in \mathbb [2,\infty]\times [2,\infty]\setminus\{(2,\infty)\}$, provided that  \eqref{con-reg} holds with $\gamma=1$ and the inequality 
$
 	\frac {d-1}2  (\frac 12 - \frac1r) \ge  \frac \alpha q
$
 holds.

Since ${\rm Id}=P_{\le 0}+ \sum_{j>0} P_j$, we have 
\[\|U_t^\gamma f \|_{L_t^q(\mathrm{d}\mu; L_x^r)} \le  \|U_t^\gamma P_{\le 0} f \|_{L_t^q(\mathrm{d}\mu; L_x^r)}+ \|\sum_{j>0} U_t^\gamma  P_jf \|_{L_t^q(\mathrm{d}\mu; L_x^r)} .\]
Since $r\ge 2$, using  Berstein's inequality and Plancherel's theorem, we note that $\|U_t^\gamma P_{\le 0} f \|_{L_x^r}\le C\|P_{\le 0} f \|_{L_x^2(\mathbb{R}^d)}$. 
Thus,  $\|U_t^\gamma P_{\le 0} f \|_{L_t^q(\mathrm{d}\mu; L_x^r)}\le C \|\mu\|^{1/q} \|f\|_{H^s(\mathbb{R}^d)}$, so we need only  to handle the remaining part. 

Using  the Littlewood--Paley inequality, we have
\[ \|\sum_{j>0} U_t^\gamma  P_jf \|_{L_x^r} \le C\Big\| \Big(\sum_{j>0} |U_t^\gamma P_j f|^2 \Big)^{1/2}\Big\|_{L^r_x(\mathbb{R}^d)}.\]
Since $2\le r, q$,  Minkowski's inequality yields 
	\begin{align*}
		 \|\sum_{j>0} U_t^\gamma  P_jf \|_{L_t^q(\mathrm{d}\mu; L_x^r)} 
		&\leq C \Big(\sum_{j>0} \| U_t^\gamma P_j f\|_{L_t^q(\mathrm{d}\mu; L_x^r)}^2 \Big)^{1/2}.
	\end{align*}
	Applying the assumption \eqref{assum} and using $\tilde P_j$,  we have 
	\begin{align*}
		 \|\sum_{j>0} U_t^\gamma  P_jf \|_{L_t^q(\mathrm{d}\mu; L_x^r)} 
		\lesssim  B \Big(\sum_{j>0} 2^{2js} \| \tilde P_j f\|_{L^2_x}^2 \Big)^{1/2}\le B \|f\|_{H^s(\mathbb{R}^d)}.
	\end{align*}
	This completes the proof.

